import '../core/constants.dart';
import '../core/formatters.dart';
import '../models/alert_event.dart';
import '../models/app_user.dart';
import 'insights_engine.dart';

/// Plain-text reports for doctors and hospitals (sent by SMS / email / copy).
abstract final class ReportService {
  static const _footer =
      'Generated by the ${AppConstants.appName} app (student prototype, not a certified medical device). '
      'Values are sensor estimates, not a diagnosis.';

  static String _vitalsLine(VitalsSnapshot v) => [
        if (v.peakHr != null) 'peak HR ${v.peakHr!.round()} bpm',
        if (v.minSpo2 != null) 'min SpO2 ${v.minSpo2!.round()}%',
        if (v.minHrv != null) 'min HRV ${v.minHrv!.round()} ms',
        if (v.peakResp != null) 'peak breathing ${v.peakResp!.round()}/min',
      ].join(', ');

  static String _medical(AppUser? p) {
    final m = p?.medical;
    if (m == null) return '';
    final lines = [
      if (m.seizureTypes.isNotEmpty) 'Seizure types: ${m.seizureTypes}',
      if (m.medications.isNotEmpty) 'Medications: ${m.medications}',
      if (m.allergies.isNotEmpty) 'Allergies: ${m.allergies}',
      if (m.bloodType.isNotEmpty) 'Blood type: ${m.bloodType}',
    ];
    return lines.isEmpty ? '' : '\n${lines.join('\n')}\n';
  }

  static String event(AlertEvent e, AppUser? patient) {
    final b = StringBuffer()
      ..writeln('${AppConstants.appName} event report')
      ..writeln('Patient: ${patient?.name ?? e.patientName}')
      ..writeln('Date: ${Fmt.dateFull(e.startedAt)}')
      ..writeln('Event: ${e.title}')
      ..writeln('Outcome: ${e.outcome}');
    if (e.duration != null) b.writeln('Duration: ${Fmt.duration(e.duration!)}');
    b.writeln('Detected from: ${e.triggers.join(' + ')} (confidence ${e.confidence.toStringAsFixed(2)})');
    final vitals = _vitalsLine(e.vitals);
    if (vitals.isNotEmpty) b.writeln('Vitals: $vitals');
    b.writeln('\nTimeline:');
    for (final t in e.timeline) {
      b.writeln('  ${Fmt.timeSec(t.at)}  ${t.label} (${Fmt.offset(t.at.difference(e.startedAt))})');
    }
    if (e.location != null) {
      b.writeln('\nLocation: ${e.location!.lat.toStringAsFixed(5)}, ${e.location!.lng.toStringAsFixed(5)}');
    }
    b
      ..write(_medical(patient))
      ..writeln()
      ..writeln(_footer);
    return b.toString();
  }

  /// Seizure timeline for the doctor: summary + one line per event.
  static String history(List<AlertEvent> events, AppUser? patient) {
    final r = InsightsEngine.analyze(events);
    final real = events.where((e) => !e.isFalseAlarm).toList();
    final b = StringBuffer()
      ..writeln('${AppConstants.appName} seizure log')
      ..writeln('Patient: ${patient?.name ?? (events.isEmpty ? '' : events.first.patientName)}')
      ..writeln('Generated: ${Fmt.dateFull(DateTime.now())}')
      ..writeln()
      ..writeln('Summary')
      ..writeln('  Events recorded: ${real.length} (plus ${r.falseAlarms} cancelled false alarms)')
      ..writeln('  Seizures this week: ${r.seizuresThisWeek} · last week: ${r.seizuresLastWeek} · '
          'last 30 days: ${r.seizuresThisMonth}');
    if (r.seizureFreeDays != null) b.writeln('  Days since last seizure: ${r.seizureFreeDays}');
    if (r.longSeizures > 0) b.writeln('  Seizures over ${AppConstants.longSeizure.inMinutes} min: ${r.longSeizures}');
    if (r.avgDuration != null) b.writeln('  Average duration: ${Fmt.duration(r.avgDuration!)}');
    if (r.longest != null) b.writeln('  Longest: ${Fmt.duration(r.longest!)}');
    if (r.avgPeakHr != null) b.writeln('  Avg peak HR: ${r.avgPeakHr!.round()} bpm');
    if (r.avgMinSpo2 != null) b.writeln('  Avg lowest SpO2: ${r.avgMinSpo2!.round()}%');
    b.write(_medical(patient));
    b
      ..writeln()
      ..writeln('Timeline (newest first)');
    for (final e in real) {
      final dur = e.duration == null ? '' : ' · ${Fmt.duration(e.duration!)}';
      final v = _vitalsLine(e.vitals);
      b.writeln('  ${Fmt.dateFull(e.startedAt)} · ${e.title}$dur${v.isEmpty ? '' : ' · $v'}');
    }
    b
      ..writeln()
      ..writeln(_footer);
    return b.toString();
  }
}
